<?php
require_once dirname(__DIR__,2).'/app/helpers.php';require_role('admin');require_once dirname(__DIR__,2).'/app/Services/AdminOperationsService.php';$svc=new AdminOperationsService(Database::connection());$q=trim($_GET['q']??'');$rows=$svc->accounts($q);$error=null;$success=null;if($_SERVER['REQUEST_METHOD']==='POST'){try{verify_csrf();$svc->setAccountStatus((int)$_POST['id'],$_POST['status']);$success=t('Account status updated.');$rows=$svc->accounts($q);}catch(Throwable $e){$error=$e->getMessage();}}
?><!doctype html><html lang="<?=e(current_locale())?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e(t('Accounts'))?> - <?=e(t('Admin'))?></title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body><div class="container-fluid p-4"><div class="d-flex justify-content-between mb-4"><h2><?=e(t('Account Operations'))?></h2><a href="<?=url('admin/')?>"><?=e(t('Admin dashboard'))?></a></div><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><?php if($success):?><div class="alert alert-success"><?=e($success)?></div><?php endif;?><form class="mb-4"><div class="input-group"><input name="q" value="<?=e($q)?>" class="form-control" placeholder="<?=e(t('Account number, name or email'))?>"><button class="btn btn-primary"><?=e(t('Search'))?></button></div></form><div class="card shadow-sm border-0"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th><?=e(t('Account'))?></th><th><?=e(t('Customer'))?></th><th><?=e(t('Type'))?></th><th><?=e(t('Balance'))?></th><th><?=e(t('Status'))?></th><th><?=e(t('Action'))?></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['account_number'])?></td><td><?=e($r['first_name'].' '.$r['last_name'])?><br><small><?=e($r['email'])?></small></td><td><?=e(tx_label($r['account_type']))?></td><td>$<?=number_format((float)$r['available_balance'],2)?></td><td><?=e(tx_label($r['status']))?></td><td><form method="post" class="d-flex gap-1"><?=csrf_field()?><input type="hidden" name="id" value="<?=$r['id']?>"><select name="status" class="form-select form-select-sm"><option>active</option><option>blocked</option><option>closed</option></select><button class="btn btn-sm btn-outline-primary"><?=e(t('Update'))?></button></form></td></tr><?php endforeach;?></tbody></table></div></div></div></body></html>
